challenge.code:
const P = ctx.params;
const progs = P.programs;
let idx = -1, lives = P.lives, tagged = 0, right = 0, card = null, judged = false;
ctx.app.stage.eventMode = 'static';
function hud() { ctx.api.setScore(right); ctx.api.setGoal(tagged + ' / ' + progs.length + '   lives ' + lives); }
function makeCard(p) {
  const c = new PIXI.Container();
  const texts = p.lines.map((ln, i) => { const t = ctx.text(ln, { size: 13, mono: true, color: ctx.colors.ink }); t.x = 18; t.y = 16 + i * 20; return t; });
  let w = 210;
  for (const t of texts) if (t.width > w) w = t.width;
  const bw = Math.min(ctx.width - 16, w + 36), bh = 32 + p.lines.length * 20;
  const g = new PIXI.Graphics();
  g.roundRect(0, 0, bw, bh, 14).fill({ color: 0x0b1220, alpha: .94 }).stroke({ width: 2, color: ctx.colors.g2, alpha: .75 });
  c.addChild(g);
  for (const t of texts) c.addChild(t);
  c.cardW = bw; c.cardH = bh; c.broken = p.broken; c.why = p.why;
  return c;
}
function next() {
  if (card) { card.destroy({ children: true }); card = null; }
  idx++; judged = false;
  if (idx >= progs.length) { ctx.api.win('Six programs, read the way the runtime reads them.'); return; }
  card = makeCard(progs[idx]);
  card.x = ctx.width + 10; card.y = 30;
  ctx.stage.addChild(card);
}
function settle(ok, why) {
  tagged++;
  if (ok) right++; else lives--;
  hud();
  const flash = new PIXI.Graphics();
  flash.roundRect(0, 0, card.cardW, card.cardH, 14).fill({ color: ok ? ctx.colors.good : ctx.colors.bad, alpha: .3 });
  card.addChild(flash);
  const dead = lives <= 0;
  gsap.to(card, { alpha: 0, duration: .3, onComplete: () => { if (dead) ctx.api.fail(why); else next(); } });
}
function judge(saysBroken) {
  if (!card || judged) return;
  judged = true;
  settle(saysBroken === card.broken, card.why);
}
function btn(label, color, xf, onTap) {
  const b = ctx.chip(label, { color: color, textColor: 0x04101a, size: 12, minWidth: 148 });
  b.x = ctx.width * xf; b.y = ctx.height - 26;
  b.eventMode = 'static'; b.cursor = 'pointer';
  b.on('pointertap', onTap);
  ctx.stage.addChild(b);
}
btn('SHIPS', ctx.colors.good, .27, () => judge(false));
btn('SILENTLY BROKEN', ctx.colors.bad, .73, () => judge(true));
ctx.onTick((dt) => {
  if (!card || judged) return;
  card.x -= (P.speed || 1.7) * dt;
  if (card.x + card.cardW < -10) { judged = true; settle(false, 'That one scrolled past untagged.'); }
});
next();
hud();

